select case when duration_sec >= 434 then 'high' when duration_sec >= 142 then 'mid' else 'low' end duration_sec_bucket, event_type, page, count(case when event_type = 'purchase' then 1 end) purchase_count, count(*) cnt, sum(case when event_type = 'click' then 1 else 0 end) click_count from web_events where session_id = 32 and page = '/product' and session_id in (16, 18, 32) group by 1, 2, 3;
